public class Element_hasClass_TriageGen1Test {

    @Test
    public void test_empty_class_attribute() {
        Element element = new Element("div");
        assertTrue(element.hasClass("")); // len == 0, return false
    }

    @Test
    public void test_short_class_attribute_less_than_want_len() {
        Element element = new Element("div");
        element.attr("class", "short");
        assertFalse(element.hasClass("longer")); // len < wantLen, return false
    }

    @Test
    public void test_long_class_attribute_equals_want_len() {
        Element element = new Element("div");
        element.attr("class", "longer");
        assertTrue(element.hasClass("longer")); // len == wantLen, regionMatches
    }

    @Test
    public void test_long_class_attribute_not_equals_want_len() {
        Element element = new Element("div");
        element.attr("class", "longer");
        assertTrue(element.hasClass("longerer")); // len != wantLen, regionMatches
    }

    @Test
    public void test_class_attribute_with_whitespace() {
        Element element = new Element("div");
        element.attr("class", "longer  longerer");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_multiple_whitespace() {
        Element element = new Element("div");
        element.attr("class", "longer   longerer");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_whitespace_at_start() {
        Element element = new Element("div");
        element.attr("class", " longer longerer");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_whitespace_at_end() {
        Element element = new Element("div");
        element.attr("class", "longer longerer ");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_multiple_class_names() {
        Element element = new Element("div");
        element.attr("class", "longer longerer shorter");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_special_characters() {
        Element element = new Element("div");
        element.attr("class", "longer~longerer!shorter");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_non_ascii_characters() {
        Element element = new Element("div");
        element.attr("class", "longerälongereröshorter");
        assertTrue(element.hasClass("longer")); // regionMatches
    }

    @Test
    public void test_class_attribute_with_null() {
        Element element = new Element("div");
        element.attr("class", null);
        assertFalse(element.hasClass("longer")); // len == 0, return false
    }

    @Test
    public void test_class_attribute_with_empty_string() {
        Element element = new Element("div");
        element.attr("class", "");
        assertFalse(element.hasClass("longer")); // len == 0, return false
    }
}
